contracts/BotSettings.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title BotSettings
 * @dev Store AI bot configuration on-chain for transparency and safety
 * 
 * Safety Features:
 * - Max bet limits per market
 * - Daily and weekly budget caps
 * - Minimum AI confidence threshold
 * - Rate limiting (cooldown, max bets per day)
 * - Emergency stop loss
 * - Category whitelist
 */

contract BotSettings is Ownable, ReentrancyGuard {
    // ============================================================================
    // STRUCTS
    // ============================================================================

    struct UserBotConfig {
        bool isActive;
        uint256 maxBetPerMarket;      // Max USDT per single bet (6 decimals)
        uint256 dailyBudget;          // Max USDT per day
        uint256 weeklyBudget;         // Max USDT per week
        uint256 minConfidence;        // Min AI confidence (0-100)
        uint256 maxBetsPerDay;        // Max number of bets per day
        uint256 cooldownMinutes;      // Minutes between bets
        uint256 emergencyStopLoss;    // Stop if losses exceed this
        uint256 lastBetTimestamp;     // Last bet timestamp
        uint256 dailySpent;           // Spent today
        uint256 weeklySpent;          // Spent this week
        uint256 totalLosses;          // Cumulative losses
        uint256 betsToday;            // Bets placed today
        uint256 lastResetDay;         // Last daily reset
        uint256 lastResetWeek;        // Last weekly reset
    }

    // ============================================================================
    // STATE VARIABLES
    // ============================================================================

    mapping(address => UserBotConfig) public botConfigs;
    mapping(address => string[]) public allowedCategories;
    mapping(address => bool) public emergencyStop;
    mapping(address => mapping(string => bool)) public hasPlacedBet; // user => marketId => placed

    // ============================================================================
    // EVENTS
    // ============================================================================

    event BotConfigured(
        address indexed user,
        uint256 maxBetPerMarket,
        uint256 dailyBudget,
        uint256 weeklyBudget,
        uint256 minConfidence
    );
    
    event BotActivated(address indexed user, uint256 timestamp);
    event BotDeactivated(address indexed user, uint256 timestamp);
    
    event BetRecorded(
        address indexed user,
        string marketId,
        uint256 amount,
        uint256 timestamp
    );
    
    event EmergencyStopTriggered(
        address indexed user,
        string reason,
        uint256 timestamp
    );
    
    event BudgetReset(
        address indexed user,
        string resetType,
        uint256 timestamp
    );

    // ============================================================================
    // CONSTRUCTOR
    // ============================================================================

    constructor() Ownable(msg.sender) {}

    // ============================================================================
    // CONFIGURATION
    // ============================================================================

    function configureBotSettings(
        uint256 _maxBetPerMarket,
        uint256 _dailyBudget,
        uint256 _weeklyBudget,
        uint256 _minConfidence,
        uint256 _maxBetsPerDay,
        uint256 _cooldownMinutes,
        uint256 _emergencyStopLoss,
        string[] memory _allowedCategories
    ) external {
        require(_maxBetPerMarket >= 5 * 10**6, "Min bet 5 USDT");
        require(_maxBetPerMarket <= 1000 * 10**6, "Max bet 1000 USDT");
        require(_minConfidence >= 60 && _minConfidence <= 95, "Confidence 60-95%");
        require(_dailyBudget >= _maxBetPerMarket, "Daily budget too low");
        require(_weeklyBudget >= _dailyBudget, "Weekly budget too low");
        require(_maxBetsPerDay > 0 && _maxBetsPerDay <= 50, "Max bets 1-50");
        require(_cooldownMinutes >= 5 && _cooldownMinutes <= 120, "Cooldown 5-120 min");
        require(_allowedCategories.length > 0, "Need at least 1 category");

        UserBotConfig storage config = botConfigs[msg.sender];
        
        config.maxBetPerMarket = _maxBetPerMarket;
        config.dailyBudget = _dailyBudget;
        config.weeklyBudget = _weeklyBudget;
        config.minConfidence = _minConfidence;
        config.maxBetsPerDay = _maxBetsPerDay;
        config.cooldownMinutes = _cooldownMinutes;
        config.emergencyStopLoss = _emergencyStopLoss;
        
        // Reset counters if first time
        if (config.lastResetDay == 0) {
            config.lastResetDay = block.timestamp / 1 days;
            config.lastResetWeek = block.timestamp / 1 weeks;
        }

        // Update categories
        delete allowedCategories[msg.sender];
        for (uint i = 0; i < _allowedCategories.length; i++) {
            allowedCategories[msg.sender].push(_allowedCategories[i]);
        }

        emit BotConfigured(
            msg.sender,
            _maxBetPerMarket,
            _dailyBudget,
            _weeklyBudget,
            _minConfidence
        );
    }

    // ============================================================================
    // BOT CONTROL
    // ============================================================================

    function activateBot() external {
        require(botConfigs[msg.sender].maxBetPerMarket > 0, "Configure first");
        require(!emergencyStop[msg.sender], "Emergency stop active");
        
        botConfigs[msg.sender].isActive = true;
        
        emit BotActivated(msg.sender, block.timestamp);
    }

    function deactivateBot() external {
        botConfigs[msg.sender].isActive = false;
        
        emit BotDeactivated(msg.sender, block.timestamp);
    }

    function triggerEmergencyStop(string memory reason) external {
        emergencyStop[msg.sender] = true;
        botConfigs[msg.sender].isActive = false;
        
        emit EmergencyStopTriggered(msg.sender, reason, block.timestamp);
    }

    function clearEmergencyStop() external {
        emergencyStop[msg.sender] = false;
    }

    // ============================================================================
    // BET VALIDATION
    // ============================================================================

    function canPlaceBet(
        address user,
        string memory marketId,
        string memory category,
        uint256 betAmount,
        uint256 aiConfidence
    ) external view returns (bool, string memory) {
        UserBotConfig memory config = botConfigs[user];

        // Check 1: Bot active?
        if (!config.isActive) {
            return (false, "Bot not active");
        }

        // Check 2: Emergency stop?
        if (emergencyStop[user]) {
            return (false, "Emergency stop triggered");
        }

        // Check 3: Already bet on this market?
        if (hasPlacedBet[user][marketId]) {
            return (false, "Already bet on this market");
        }

        // Check 4: Category allowed?
        bool categoryAllowed = false;
        string[] memory categories = allowedCategories[user];
        for (uint i = 0; i < categories.length; i++) {
            if (keccak256(bytes(categories[i])) == keccak256(bytes(category))) {
                categoryAllowed = true;
                break;
            }
        }
        if (!categoryAllowed) {
            return (false, "Category not allowed");
        }

        // Check 5: Confidence high enough?
        if (aiConfidence < config.minConfidence) {
            return (false, "Confidence below threshold");
        }

        // Check 6: Bet amount within limit?
        if (betAmount > config.maxBetPerMarket) {
            return (false, "Exceeds max bet per market");
        }

        // Check 7: Reset daily/weekly if needed
        uint256 currentDay = block.timestamp / 1 days;
        uint256 currentWeek = block.timestamp / 1 weeks;

        uint256 dailySpent = config.dailySpent;
        uint256 weeklySpent = config.weeklySpent;
        uint256 betsToday = config.betsToday;

        if (currentDay > config.lastResetDay) {
            dailySpent = 0;
            betsToday = 0;
        }
        if (currentWeek > config.lastResetWeek) {
            weeklySpent = 0;
        }

        // Check 8: Daily budget?
        if (dailySpent + betAmount > config.dailyBudget) {
            return (false, "Daily budget exceeded");
        }

        // Check 9: Weekly budget?
        if (weeklySpent + betAmount > config.weeklyBudget) {
            return (false, "Weekly budget exceeded");
        }

        // Check 10: Cooldown?
        if (block.timestamp < config.lastBetTimestamp + (config.cooldownMinutes * 60)) {
            return (false, "Cooldown active");
        }

        // Check 11: Max bets per day?
        if (betsToday >= config.maxBetsPerDay) {
            return (false, "Max bets per day reached");
        }

        // Check 12: Stop loss?
        if (config.totalLosses >= config.emergencyStopLoss) {
            return (false, "Stop loss triggered");
        }

        return (true, "All checks passed");
    }

    // ============================================================================
    // BET RECORDING
    // ============================================================================

    function recordBet(
        string memory marketId,
        string memory category,
        uint256 amount,
        uint256 aiConfidence
    ) external nonReentrant {
        (bool canBet, string memory reason) = this.canPlaceBet(
            msg.sender,
            marketId,
            category,
            amount,
            aiConfidence
        );
        
        require(canBet, reason);

        UserBotConfig storage config = botConfigs[msg.sender];

        // Reset counters if needed
        uint256 currentDay = block.timestamp / 1 days;
        uint256 currentWeek = block.timestamp / 1 weeks;

        if (currentDay > config.lastResetDay) {
            config.dailySpent = 0;
            config.betsToday = 0;
            config.lastResetDay = currentDay;
            emit BudgetReset(msg.sender, "daily", block.timestamp);
        }
        if (currentWeek > config.lastResetWeek) {
            config.weeklySpent = 0;
            config.lastResetWeek = currentWeek;
            emit BudgetReset(msg.sender, "weekly", block.timestamp);
        }

        // Update counters
        config.dailySpent += amount;
        config.weeklySpent += amount;
        config.betsToday += 1;
        config.lastBetTimestamp = block.timestamp;
        
        // Mark market as bet on
        hasPlacedBet[msg.sender][marketId] = true;

        emit BetRecorded(msg.sender, marketId, amount, block.timestamp);
    }

    function recordLoss(uint256 lossAmount) external {
        UserBotConfig storage config = botConfigs[msg.sender];
        config.totalLosses += lossAmount;

        // Auto-trigger emergency stop if stop loss reached
        if (config.totalLosses >= config.emergencyStopLoss) {
            emergencyStop[msg.sender] = true;
            config.isActive = false;
            emit EmergencyStopTriggered(
                msg.sender,
                "Stop loss reached",
                block.timestamp
            );
        }
    }

    // ============================================================================
    // GETTERS
    // ============================================================================

    function getBotConfig(address user) external view returns (
        bool isActive,
        uint256 maxBetPerMarket,
        uint256 dailyBudget,
        uint256 weeklyBudget,
        uint256 minConfidence,
        uint256 maxBetsPerDay,
        uint256 cooldownMinutes,
        uint256 emergencyStopLoss
    ) {
        UserBotConfig memory config = botConfigs[user];
        return (
            config.isActive,
            config.maxBetPerMarket,
            config.dailyBudget,
            config.weeklyBudget,
            config.minConfidence,
            config.maxBetsPerDay,
            config.cooldownMinutes,
            config.emergencyStopLoss
        );
    }

    function getBotStats(address user) external view returns (
        uint256 dailySpent,
        uint256 weeklySpent,
        uint256 totalLosses,
        uint256 betsToday,
        uint256 lastBetTimestamp,
        bool emergencyStopActive
    ) {
        UserBotConfig memory config = botConfigs[user];
        
        // Adjust for resets
        uint256 currentDay = block.timestamp / 1 days;
        uint256 currentWeek = block.timestamp / 1 weeks;

        uint256 _dailySpent = config.dailySpent;
        uint256 _weeklySpent = config.weeklySpent;
        uint256 _betsToday = config.betsToday;

        if (currentDay > config.lastResetDay) {
            _dailySpent = 0;
            _betsToday = 0;
        }
        if (currentWeek > config.lastResetWeek) {
            _weeklySpent = 0;
        }

        return (
            _dailySpent,
            _weeklySpent,
            config.totalLosses,
            _betsToday,
            config.lastBetTimestamp,
            emergencyStop[user]
        );
    }

    function getAllowedCategories(address user) external view returns (string[] memory) {
        return allowedCategories[user];
    }

    function isBotActive(address user) external view returns (bool) {
        return botConfigs[user].isActive && !emergencyStop[user];
    }
}

contracts/Casino.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title Casino
 * @dev Multi-game casino contract with provably fair randomness
 * 
 * Supported Games:
 * - Roulette (0-36, pays 35:1)
 * - Dice (1-6, pays 5:1)
 * - Coin Flip (Heads/Tails, pays 1.95:1)
 * - High/Low Dice (Over/Under 3.5, pays 1.9:1)
 * 
 * Security Features:
 * - ReentrancyGuard
 * - Pausable
 * - Bet limits per game
 * - House edge (2-5% depending on game)
 * - Anti-manipulation cooldown
 */

enum GameType {
    ROULETTE,      // 0-36, straight bet
    DICE,          // 1-6, specific number
    COIN_FLIP,     // 0=Heads, 1=Tails
    HIGH_LOW_DICE  // 0=Low(1-3), 1=High(4-6)
}

enum GameResult {
    WIN,
    LOSS
}

struct Bet {
    address player;
    GameType gameType;
    uint256 amount;
    uint256 prediction;
    uint256 result;
    GameResult outcome;
    uint256 payout;
    uint256 timestamp;
    uint256 blockNumber;
}

contract Casino is Ownable, ReentrancyGuard, Pausable {
    // ============================================================================
    // STATE VARIABLES
    // ============================================================================

    IERC20 public usdt;
    address public houseWallet;

    // Bet tracking
    mapping(address => Bet[]) public playerBets;
    mapping(address => uint256) public lastBetTimestamp;
    Bet[] public allBets;

    // Statistics
    mapping(address => uint256) public totalWagered;
    mapping(address => uint256) public totalWon;
    mapping(address => uint256) public totalLost;
    uint256 public houseTotalWagered;
    uint256 public houseTotalPaidOut;
    uint256 public houseTotalProfit;

    // Game Configuration
    uint256 public constant MIN_BET = 1 * 10**6;        // 1 USDT (6 decimals)
    uint256 public constant MAX_BET = 1000 * 10**6;     // 1000 USDT
    uint256 public constant COOLDOWN_SECONDS = 3;       // 3 seconds between bets
    uint256 public constant HOUSE_EDGE_BPS = 250;       // 2.5% house edge

    // Game-specific limits
    uint256 public constant ROULETTE_MAX_BET = 100 * 10**6;   // 100 USDT
    uint256 public constant DICE_MAX_BET = 200 * 10**6;       // 200 USDT
    uint256 public constant COIN_FLIP_MAX_BET = 500 * 10**6;  // 500 USDT
    uint256 public constant HIGH_LOW_MAX_BET = 1000 * 10**6;  // 1000 USDT

    // ============================================================================
    // EVENTS
    // ============================================================================

    event BetPlaced(
        address indexed player,
        GameType indexed gameType,
        uint256 amount,
        uint256 prediction,
        uint256 indexed betId
    );

    event BetResult(
        address indexed player,
        uint256 indexed betId,
        GameType gameType,
        uint256 prediction,
        uint256 result,
        GameResult outcome,
        uint256 payout
    );

    event HouseBalanceUpdated(
        uint256 newBalance,
        int256 change
    );

    // ============================================================================
    // CONSTRUCTOR
    // ============================================================================

    constructor(address _usdt, address _houseWallet) Ownable(msg.sender) {
        require(_usdt != address(0), "Casino: Invalid USDT address");
        require(_houseWallet != address(0), "Casino: Invalid house wallet");
        
        usdt = IERC20(_usdt);
        houseWallet = _houseWallet;
    }

    // ============================================================================
    // MAIN BETTING FUNCTION
    // ============================================================================

    /**
     * @dev Place a bet on any casino game
     * @param _gameType Type of game (0=Roulette, 1=Dice, 2=CoinFlip, 3=HighLow)
     * @param _amount Bet amount in USDT (with 6 decimals)
     * @param _prediction Player's prediction (game-specific)
     * 
     * Roulette: 0-36
     * Dice: 1-6
     * CoinFlip: 0=Heads, 1=Tails
     * HighLow: 0=Low(1-3), 1=High(4-6)
     */
    function placeBet(
        GameType _gameType,
        uint256 _amount,
        uint256 _prediction
    ) external nonReentrant whenNotPaused returns (uint256 betId) {
        // Validation
        _validateBet(msg.sender, _gameType, _amount, _prediction);

        // Transfer USDT from player to contract
        require(
            usdt.transferFrom(msg.sender, address(this), _amount),
            "Casino: USDT transfer failed"
        );

        // Generate random result
        uint256 result = _generateRandomNumber(_gameType, msg.sender);

        // Calculate outcome and payout
        (GameResult outcome, uint256 payout) = _calculateOutcome(
            _gameType,
            _amount,
            _prediction,
            result
        );

        // Create bet record
        Bet memory newBet = Bet({
            player: msg.sender,
            gameType: _gameType,
            amount: _amount,
            prediction: _prediction,
            result: result,
            outcome: outcome,
            payout: payout,
            timestamp: block.timestamp,
            blockNumber: block.number
        });

        // Store bet
        betId = allBets.length;
        allBets.push(newBet);
        playerBets[msg.sender].push(newBet);

        // Update statistics
        totalWagered[msg.sender] += _amount;
        houseTotalWagered += _amount;
        lastBetTimestamp[msg.sender] = block.timestamp;

        // Emit bet placed event
        emit BetPlaced(msg.sender, _gameType, _amount, _prediction, betId);

        // Process payout if won
        if (outcome == GameResult.WIN) {
            require(
                usdt.transfer(msg.sender, payout),
                "Casino: Payout transfer failed"
            );
            
            totalWon[msg.sender] += payout;
            houseTotalPaidOut += payout;
            
            int256 houseChange = int256(_amount) - int256(payout);
            if (houseChange > 0) {
                houseTotalProfit += uint256(houseChange);
            }
            
            emit HouseBalanceUpdated(getHouseBalance(), houseChange);
        } else {
            totalLost[msg.sender] += _amount;
            houseTotalProfit += _amount;
            emit HouseBalanceUpdated(getHouseBalance(), int256(_amount));
        }

        // Emit result event
        emit BetResult(
            msg.sender,
            betId,
            _gameType,
            _prediction,
            result,
            outcome,
            payout
        );

        return betId;
    }

    // ============================================================================
    // VALIDATION
    // ============================================================================

    function _validateBet(
        address _player,
        GameType _gameType,
        uint256 _amount,
        uint256 _prediction
    ) internal view {
        // Check cooldown
        require(
            block.timestamp >= lastBetTimestamp[_player] + COOLDOWN_SECONDS,
            "Casino: Cooldown not met (3s between bets)"
        );

        // Check minimum bet
        require(_amount >= MIN_BET, "Casino: Bet below minimum (1 USDT)");

        // Check maximum bet per game
        if (_gameType == GameType.ROULETTE) {
            require(_amount <= ROULETTE_MAX_BET, "Casino: Roulette max 100 USDT");
            require(_prediction <= 36, "Casino: Roulette number must be 0-36");
        } else if (_gameType == GameType.DICE) {
            require(_amount <= DICE_MAX_BET, "Casino: Dice max 200 USDT");
            require(_prediction >= 1 && _prediction <= 6, "Casino: Dice must be 1-6");
        } else if (_gameType == GameType.COIN_FLIP) {
            require(_amount <= COIN_FLIP_MAX_BET, "Casino: Coin flip max 500 USDT");
            require(_prediction <= 1, "Casino: Coin flip must be 0 (Heads) or 1 (Tails)");
        } else if (_gameType == GameType.HIGH_LOW_DICE) {
            require(_amount <= HIGH_LOW_MAX_BET, "Casino: High/Low max 1000 USDT");
            require(_prediction <= 1, "Casino: High/Low must be 0 (Low) or 1 (High)");
        }

        // Check house has enough balance for potential payout
        uint256 maxPayout = _calculateMaxPayout(_gameType, _amount);
        require(
            getHouseBalance() >= maxPayout,
            "Casino: Insufficient house balance"
        );
    }

    // ============================================================================
    // RANDOMNESS (Pseudo-random for demo - Use Chainlink VRF in production)
    // ============================================================================

    function _generateRandomNumber(GameType _gameType, address _player) internal view returns (uint256) {
        uint256 random = uint256(
            keccak256(
                abi.encodePacked(
                    block.timestamp,
                    block.prevrandao,
                    block.number,
                    _player,
                    allBets.length,
                    msg.sender
                )
            )
        );

        if (_gameType == GameType.ROULETTE) {
            return random % 37; // 0-36
        } else if (_gameType == GameType.DICE) {
            return (random % 6) + 1; // 1-6
        } else if (_gameType == GameType.COIN_FLIP) {
            return random % 2; // 0 or 1
        } else if (_gameType == GameType.HIGH_LOW_DICE) {
            uint256 diceRoll = (random % 6) + 1; // 1-6
            return diceRoll <= 3 ? 0 : 1; // 0=Low, 1=High
        }

        return 0;
    }

    // ============================================================================
    // PAYOUT CALCULATION
    // ============================================================================

    function _calculateOutcome(
        GameType _gameType,
        uint256 _amount,
        uint256 _prediction,
        uint256 _result
    ) internal pure returns (GameResult outcome, uint256 payout) {
        bool won = (_prediction == _result);

        if (!won) {
            return (GameResult.LOSS, 0);
        }

        // Calculate payout based on game type
        if (_gameType == GameType.ROULETTE) {
            // 35:1 payout (European Roulette single number)
            payout = _amount * 35;
        } else if (_gameType == GameType.DICE) {
            // 5:1 payout
            payout = _amount * 5;
        } else if (_gameType == GameType.COIN_FLIP) {
            // 1.95:1 payout (2.5% house edge)
            payout = (_amount * 195) / 100;
        } else if (_gameType == GameType.HIGH_LOW_DICE) {
            // 1.9:1 payout (50/50 odds with house edge)
            payout = (_amount * 190) / 100;
        }

        return (GameResult.WIN, payout);
    }

    function _calculateMaxPayout(GameType _gameType, uint256 _amount) internal pure returns (uint256) {
        if (_gameType == GameType.ROULETTE) {
            return _amount * 35;
        } else if (_gameType == GameType.DICE) {
            return _amount * 5;
        } else if (_gameType == GameType.COIN_FLIP) {
            return (_amount * 195) / 100;
        } else if (_gameType == GameType.HIGH_LOW_DICE) {
            return (_amount * 190) / 100;
        }
        return 0;
    }

    // ============================================================================
    // VIEW FUNCTIONS
    // ============================================================================

    function getHouseBalance() public view returns (uint256) {
        return usdt.balanceOf(address(this));
    }

    function getPlayerBets(address _player) external view returns (Bet[] memory) {
        return playerBets[_player];
    }

    function getPlayerStats(address _player) external view returns (
        uint256 wagered,
        uint256 won,
        uint256 lost,
        uint256 netProfit
    ) {
        wagered = totalWagered[_player];
        won = totalWon[_player];
        lost = totalLost[_player];
        netProfit = won > lost ? won - lost : 0;
    }

    function getHouseStats() external view returns (
        uint256 totalWagered_,
        uint256 totalPaidOut,
        uint256 totalProfit,
        uint256 houseBalance
    ) {
        totalWagered_ = houseTotalWagered;
        totalPaidOut = houseTotalPaidOut;
        totalProfit = houseTotalProfit;
        houseBalance = getHouseBalance();
    }

    function getBetLimits(GameType _gameType) external pure returns (uint256 min, uint256 max) {
        min = MIN_BET;
        
        if (_gameType == GameType.ROULETTE) {
            max = ROULETTE_MAX_BET;
        } else if (_gameType == GameType.DICE) {
            max = DICE_MAX_BET;
        } else if (_gameType == GameType.COIN_FLIP) {
            max = COIN_FLIP_MAX_BET;
        } else if (_gameType == GameType.HIGH_LOW_DICE) {
            max = HIGH_LOW_MAX_BET;
        }
    }

    // ============================================================================
    // ADMIN FUNCTIONS
    // ============================================================================

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function depositHouseFunds(uint256 _amount) external onlyOwner {
        require(
            usdt.transferFrom(msg.sender, address(this), _amount),
            "Casino: House deposit failed"
        );
        emit HouseBalanceUpdated(getHouseBalance(), int256(_amount));
    }

    function withdrawHouseFunds(uint256 _amount) external onlyOwner {
        require(_amount <= getHouseBalance(), "Casino: Insufficient balance");
        require(
            usdt.transfer(houseWallet, _amount),
            "Casino: Withdrawal failed"
        );
        emit HouseBalanceUpdated(getHouseBalance(), -int256(_amount));
    }

    function updateHouseWallet(address _newHouseWallet) external onlyOwner {
        require(_newHouseWallet != address(0), "Casino: Invalid address");
        houseWallet = _newHouseWallet;
    }

    // Emergency function to recover stuck tokens
    function emergencyWithdraw() external onlyOwner {
        uint256 balance = getHouseBalance();
        require(usdt.transfer(owner(), balance), "Casino: Emergency withdrawal failed");
    }
}

contracts/MarketManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./PositionToken.sol";
import "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";

contract MarketManager is ERC1155, Ownable {
    PositionToken public immutable positionToken;
    
    struct Market {
        string id;
        string sport;
        string description;
        uint256 maxStake;
        uint256 expiresAt;
        bool isSettled;
        string result; // "home", "away"
        address oracle;
    }
    
    mapping(string => Market) public markets;
    mapping(string => uint256) public marketExposure; // marketId => total exposure
    string[] public activeMarkets;
    
    uint256 public constant HOUSE_EDGE_BPS = 200; // 2%
    uint256 public constant MIN_STAKE = 0.001 ether;
    
    event MarketCreated(string indexed marketId, string sport, uint256 expiresAt);
    event PositionOpened(
        string indexed marketId, 
        address indexed user, 
        string side, 
        uint256 stake,
        uint256 odds
    );
    event MarketSettled(string indexed marketId, string result);
    
    constructor(address _positionToken) 
        ERC1155("sportsbook://{marketId}/{positionId}")
        Ownable(msg.sender)
    {
        positionToken = PositionToken(_positionToken);
    }
    
    function createMarket(
        string memory _marketId,
        string memory _sport,
        string memory _description,
        uint256 _maxStake,
        uint256 _expiresAt,
        address _oracle
    ) external onlyOwner {
        require(_expiresAt > block.timestamp + 60, "Invalid expiry");
        require(bytes(_marketId).length > 0, "Invalid market ID");
        require(markets[_marketId].expiresAt == 0, "Market exists");
        
        markets[_marketId] = Market({
            id: _marketId,
            sport: _sport,
            description: _description,
            maxStake: _maxStake,
            expiresAt: _expiresAt,
            isSettled: false,
            result: "",
            oracle: _oracle
        });
        
        activeMarkets.push(_marketId);
        emit MarketCreated(_marketId, _sport, _expiresAt);
    }
    
    function openPosition(
        string memory _quoteId,
        string memory _marketId,
        string memory _side,
        uint256 _stake,
        uint256 _odds
    ) external payable {
        Market storage market = markets[_marketId];
        require(!market.isSettled, "Market settled");
        require(block.timestamp < market.expiresAt, "Market expired");
        require(_stake >= MIN_STAKE, "Stake too small");
        require(_stake <= market.maxStake, "Stake too large");
        require(bytes(_side).length > 0, "Invalid side");
        
        // Calculate price with house edge
        uint256 priceWithEdge = (_stake * _odds * (10**18 + HOUSE_EDGE_BPS)) / 10**18;
        require(msg.value >= priceWithEdge, "Insufficient payment");
        
        // Refund excess
        if (msg.value > priceWithEdge) {
            payable(msg.sender).transfer(msg.value - priceWithEdge);
        }
        
        // Track exposure
        marketExposure[_marketId] += _stake;
        
        // Mint position NFT
        uint256 tokenId = uint256(keccak256(abi.encodePacked(_quoteId, msg.sender, block.timestamp)));
        bytes memory positionData = abi.encode(_marketId, _side, _stake, _odds);
        positionToken.mint(msg.sender, tokenId, 1, positionData);
        
        emit PositionOpened(_marketId, msg.sender, _side, _stake, _odds);
    }
    
    function settleMarket(string memory _marketId, string memory _result) external onlyOwner {
        Market storage market = markets[_marketId];
        require(!market.isSettled, "Already settled");
        require(block.timestamp >= market.expiresAt, "Market not expired");
        
        market.isSettled = true;
        market.result = _result;
        
        emit MarketSettled(_marketId, _result);
    }
    
    function getActiveMarkets() external view returns (string[] memory) {
        return activeMarkets;
    }
    
    function getMarket(string memory _marketId) external view returns (Market memory) {
        return markets[_marketId];
    }
}

